      p.push(r.condicion === 'debe' ? CONDICIONES.debe + (r.basta ? ' (al menos uno)' : '') : `${CONDICIONES[r.condicion]} → ${ACCIONES[r.accion].toLowerCase()}`);
      if (r.donde !== 'todo') p.push(DONDE[r.donde].toLowerCase());
