        o.vigentes.docs.forEach((d) => { const f = Array.isArray(d) ? d : [d], cod = normalizarCodigo(f[0]); if (!cod || vistos.has(cod)) return; vistos.add(cod); docs.push([cod, ...f.slice(1, 7).map((x) => (x == null ? '' : String(x)))]); });
