    let refs = md.areaRmdTxt ? await buscar([...base, new Filtro('areaRmdTxt', 'EQ', md.areaRmdTxt)]) : [], alcance = `${md.areaRmdTxt} · ${md.nivelTxt}`;
    if (refs.length < 2) { refs = await buscar(base); alcance = `${md.nivelTxt} (toda la planta)`; }
