    const d = await hasta(() => dialogos().find((x) => !previos.has(x) && /^Asociar F[oó]rmula/i.test(cabecera(x))), 40000);
    if (!d) throw new Error('no se abrió "Asociar fórmulas"');
    await esperar(600); await hasta(() => !ocupadoGlobal(), 40000);
