    const poner = (op, cls, icono, texto, titulo, fn) => {
      const ya = barra.querySelector('.' + cls);
      if (!on(op)) { if (ya) ya.remove(); return; }
      if (ya) return;
      const x = botonIcono(icono, texto, cls, fn); x.title = titulo;
      colocarEnBarra(barra, x);
    };
