    const fp = await leerTodoDe(modelo, 'MD_ES_FORMULA_PASO', porMd.concat(new F('esPaso', 'EQ', true)), { $select: 'mdFormulaPaso,pasoFormulaId_mdEstructuraPasoId,pasoFormulaIdPM_mdEstructuraPasoInsumoPasoId,bFlagPM,valor' });
