    const lista = [...todos.values()].filter((m) => m.codigo != null).map((m) => ({ ...m, estado: (m.estadoIdRmd && m.estadoIdRmd.contenido) || '' })).sort((a, b) => (+a.version - +b.version) || (new Date(a.fechaRegistro) - new Date(b.fechaRegistro)));
