        m.addEventListener('click', (e) => { const a = e.target.dataset.a; if (a === 'cancelar') cerrar(); else if (a === 'aceptar') { const v = ta.value.trim(); cambio(() => { encontrar(id).item.comentario = v; }); cerrar(); } });
