          const faltan = ['nombre', 'area', 'motivo'].filter((k) => !nuevo[k]); $$('[data-k]', m).forEach((i) => i.classList.toggle('falta', faltan.includes(i.dataset.k)));
          if (faltan.length && paraGuardar) { const f = $(`[data-k="${faltan[0]}"]`, m); if (f) f.focus(); return; }
