    window.__rmdStats.panel = { abrir: (todo) => { p.open = true; if (todo) grupos.forEach((sec) => sec.classList.add('abierto')); }, cerrar, grupos: GRUPOS_PANEL };
    pintar(); pintarVersion(); panelEl = p; montarPanel(); avisoVersionNueva();
